const lead = $json.body || {};

const rubricText = `Budget signal (does the lead mention or imply a budget?):\n- explicit: A specific number or range is stated (e.g. \"$5k budget\", \"$50/hr\").\n- implied: Budget is implied by scope/urgency/company size but no number given.\n- none: No budget signal at all.\n\nUrgency signal (how soon does the lead want this done?):\n- immediate: Wants to start now or within days; explicit deadline mentioned.\n- near_term: Wants to start within the next month or so; some time pressure.\n- exploratory: Just researching, no timeline mentioned.\n\nFit signal (how well does the request match target_service_offerings?):\n- strong: Directly asks for n8n/AI agent/CRM automation work.\n- adjacent: Related automation/integration/dev work, different tool or platform.\n- none: Unrelated to automation/dev work entirely.`;

const targetServiceOfferings = "n8n workflow automation, AI agent builds (Claude/GPT-powered), and CRM automation (HubSpot, GoHighLevel, Salesforce). Also in-scope: general business process automation where n8n or a similar orchestration tool is the likely implementation.";

const scoringInstructions = "Score 0-100 based on how strong all three signals are together. Explicit budget + immediate urgency + strong fit should score near the top of the range; none/none/none should score near the bottom. Weight fit_signal most heavily - a great budget for the wrong kind of work is still a poor lead for this business.";

const prompt = `You are qualifying an inbound lead for a business offering: ${targetServiceOfferings}\n\nScore the lead using these dimensions:\n\n${rubricText}\n\nScoring instructions: ${scoringInstructions}\n\nLead:\nName: ${lead.name || ''}\nEmail: ${lead.email || ''}\nCompany: ${lead.company || ''}\nMessage: ${lead.message || ''}\n\nCall submit_qualification_score with your assessment.`;

const requestBody = {
  model: "claude-opus-5",
  max_tokens: 4096,
  output_config: { effort: "low" },
  tools: [
    {
      name: "submit_qualification_score",
      description: "Submit the qualification score and reasoning for an inbound lead.",
      strict: true,
      input_schema: {
        type: "object",
        properties: {
          score: { type: "integer", description: "Qualification score from 0 to 100." },
          reasoning: { type: "string", description: "Explanation of the score, referencing all three signals." },
          budget_signal: { type: "string", enum: ["explicit", "implied", "none"] },
          urgency_signal: { type: "string", enum: ["immediate", "near_term", "exploratory"] },
          fit_signal: { type: "string", enum: ["strong", "adjacent", "none"] }
        },
        required: ["score", "reasoning", "budget_signal", "urgency_signal", "fit_signal"],
        additionalProperties: false
      }
    }
  ],
  tool_choice: { type: "tool", name: "submit_qualification_score" },
  messages: [{ role: "user", content: prompt }]
};

return [{
  json: {
    requestBody,
    lead: {
      name: lead.name || '',
      email: lead.email || '',
      company: lead.company || '',
      message: lead.message || ''
    }
  }
}];

const response = $json;

if (response.stop_reason === 'refusal') {
  throw new Error('Claude declined to score this lead (refusal): ' + JSON.stringify(response.stop_details || {}));
}

const toolUse = (response.content || []).find(b => b.type === 'tool_use');
if (!toolUse) {
  throw new Error('No tool_use block found in Claude scoring response');
}

const result = toolUse.input;
const score = result.score;

let recommendedAction;
if (score >= 70) {
  recommendedAction = 'high_priority_outreach';
} else if (score >= 40) {
  recommendedAction = 'nurture';
} else {
  recommendedAction = 'log_only';
}

const lead = $('Build Scoring Request').first().json.lead;
const nameParts = (lead.name || '').trim().split(' ');
const firstname = nameParts[0] || '';
const lastname = nameParts.slice(1).join(' ') || '';

return [{
  json: {
    ...lead,
    firstname,
    lastname,
    score,
    reasoning: result.reasoning,
    budget_signal: result.budget_signal,
    urgency_signal: result.urgency_signal,
    fit_signal: result.fit_signal,
    recommended_action: recommendedAction
  }
}];

const lead = $('Parse Score').first().json;

const prompt = `Write a short, personalized outreach email to a lead who just qualified as\nhigh-priority for an n8n workflow automation / AI agent / CRM automation business.\n\nLead:\nName: ${lead.name}\nCompany: ${lead.company}\nTheir message: ${lead.message}\n\nWhy they qualified: ${lead.reasoning}\n\nWrite a brief, warm, non-salesy email that references their specific request, proposes\na short call to scope the work, and signs off simply as \"the team\". No markdown, no\nplaceholders like [Name] - use the actual details given. Call submit_draft_email with\nthe subject and body.`;

const requestBody = {
  model: "claude-opus-5",
  max_tokens: 2048,
  output_config: { effort: "medium" },
  tools: [
    {
      name: "submit_draft_email",
      description: "Submit the subject line and body for a personalized outreach email.",
      strict: true,
      input_schema: {
        type: "object",
        properties: {
          subject: { type: "string", description: "Short, specific email subject line." },
          body: { type: "string", description: "Plain-text email body, first-person, no markdown/HTML." }
        },
        required: ["subject", "body"],
        additionalProperties: false
      }
    }
  ],
  tool_choice: { type: "tool", name: "submit_draft_email" },
  messages: [{ role: "user", content: prompt }]
};

return [{ json: { requestBody, leadEmail: lead.email } }];

const response = $json;

if (response.stop_reason === 'refusal') {
  throw new Error('Claude declined to draft outreach email (refusal): ' + JSON.stringify(response.stop_details || {}));
}

const toolUse = (response.content || []).find(b => b.type === 'tool_use');
if (!toolUse) {
  throw new Error('No tool_use block found in Claude draft response');
}

const leadEmail = $('Build Draft Request').first().json.leadEmail;

return [{
  json: {
    subject: toolUse.input.subject,
    body: toolUse.input.body,
    leadEmail
  }
}];
